CREATE TABLE IF NOT EXISTS employees(id INTEGER PRIMARY KEY AUTO_INCREMENT,name TEXT,department TEXT,email TEXT,position TEXT,phone TEXT,status TEXT);
CREATE TABLE IF NOT EXISTS projects(id INTEGER PRIMARY KEY AUTO_INCREMENT,title TEXT,status TEXT,owner TEXT,budget INTEGER,progress INTEGER,deadline TEXT,description TEXT);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTO_INCREMENT,project_id INTEGER,title TEXT,assignee TEXT,status TEXT,priority TEXT,due TEXT);
CREATE TABLE IF NOT EXISTS milestones(id INTEGER PRIMARY KEY AUTO_INCREMENT,project_id INTEGER,title TEXT,due TEXT,status TEXT);
CREATE TABLE IF NOT EXISTS tickets(id INTEGER PRIMARY KEY AUTO_INCREMENT,title TEXT,status TEXT,category TEXT,priority TEXT,requester TEXT,assignee TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY AUTO_INCREMENT,ticket_id INTEGER,author TEXT,body TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS assets(id INTEGER PRIMARY KEY AUTO_INCREMENT,name TEXT,tag TEXT,status TEXT,category TEXT,holder TEXT);
CREATE TABLE IF NOT EXISTS loans(id INTEGER PRIMARY KEY AUTO_INCREMENT,asset_id INTEGER,employee TEXT,borrowed TEXT,returned TEXT,status TEXT);
CREATE TABLE IF NOT EXISTS expenses(id INTEGER PRIMARY KEY AUTO_INCREMENT,title TEXT,amount INTEGER,status TEXT,requester TEXT,category TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY AUTO_INCREMENT,name TEXT,folder TEXT,owner TEXT,size TEXT,visibility TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS attendance(id INTEGER PRIMARY KEY AUTO_INCREMENT,employee TEXT,day TEXT,status TEXT);
CREATE TABLE IF NOT EXISTS leave_requests(id INTEGER PRIMARY KEY AUTO_INCREMENT,employee TEXT,kind TEXT,start_date TEXT,end_date TEXT,status TEXT);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTO_INCREMENT,title TEXT,body TEXT,created TEXT,is_read INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS activity(id INTEGER PRIMARY KEY AUTO_INCREMENT,actor TEXT,action TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS settings(k VARCHAR(191) PRIMARY KEY,v TEXT);
CREATE TABLE IF NOT EXISTS exports(id INTEGER PRIMARY KEY AUTO_INCREMENT,title TEXT,created TEXT,actor TEXT);
